final class ScanListener {
    private volatile QueueReader reader = newReader();
    private final Resource cracHandler = new Resource() {
        // 1. stop reading, finish the message in hand, and close the queue connection
        @Override public void beforeCheckpoint(Context<? extends Resource> c) { stopReading(); reader.close(); }
        // 2. a new reader connects again after the restore
        @Override public void afterRestore(Context<? extends Resource> c) { reader = newReader(); startReading(); }
    };

    ScanListener() { Core.getGlobalContext().register(cracHandler); }
}

